/**
 * Generates lib/catalogData.ts from data/seed/manifest.json (Metro needs static requires).
 * Run after adding a plant file: `yarn catalog` (a test fails if it is out of date).
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const manifest = JSON.parse(fs.readFileSync(path.join(ROOT, 'data/seed/manifest.json'), 'utf8'));
const lines = [
  '// Generated by scripts/build-catalog.js from data/seed/manifest.json — do not edit by hand.',
  "import { buildCatalog } from './catalog';",
  "import { GeographyData, HealthData, Plant, ReferenceData, SeedManifest } from './types';",
  '',
  'const plants: Plant[] = [',
  ...manifest.plantFiles.map((f) => `  require('../data/seed/plants/${f}'),`),
  '];',
  '',
  'export const catalog = buildCatalog(',
  "  require('../data/seed/manifest.json') as SeedManifest,",
  "  require('../data/seed/reference.json') as ReferenceData,",
  "  require('../data/seed/geography.json') as GeographyData,",
  "  require('../data/seed/health.json') as HealthData,",
  '  plants,',
  ');',
  '',
];
fs.writeFileSync(path.join(ROOT, 'lib/catalogData.ts'), lines.join('\n'));
console.log(`lib/catalogData.ts: ${manifest.plantFiles.length} plants`);
